"""Deduce and format conversation-repair occurrences from tracker audit events.

Builds the ``--- Conversation Repair ---`` section in eval ``run_N.txt`` (after
the run header, before Quality Criteria). Informational only — does not affect
pass/fail.

One ``- {label}`` bullet per qualifying event, in tracker order (repeats allowed,
no dedupe). Non-empty fields only, in :data:`REPAIR_FIELD_ORDER`. When nothing
qualifies, the section still renders with ``observed: none``.

Repair signals:

+------------------+----------------------------------+---------------------------+
| Report label     | Tracker event                    | Report fields             |
+==================+==================================+===========================+
| ``correction``   | memory write (``MemorySet`` /    | ``memory_key``,           |
|                  | ``MemoryCleared``)  with         | ``step_id``,              |
|                  |  ``metadata.correction``         | ``skill_id``              |
+------------------+----------------------------------+---------------------------+
| ``cancellation`` | ``SkillCancelled``               | ``step_id``, ``skill_id`` |
+------------------+----------------------------------+---------------------------+
| ``digression``   | ``SkillInterrupted`` with        | ``from_step_id``,         |
|                  | ``metadata.digression``          | ``from_skill_id``,        |
|                  |                                  | ``to_step_id``,           |
|                  |                                  | ``to_skill_id``           |
+------------------+----------------------------------+---------------------------+
| ``out_of_scope`` | ``UnsupportedRequestClassified`` | ``reason``                |
|                  | (``label ==                      | (truncated to             |
|                  |  "in_domain_out_of_scope"``)     | :data:`REASON_MAX_LENGTH`;|
|                  |                                  | never ``user_message``)   |
+------------------+----------------------------------+---------------------------+
| ``out_of_domain``| ``UnsupportedRequestClassified`` | ``reason``                |
|                  | (``label ==                      | (truncated to             |
|                  |  "out_of_domain_out_of_scope"``) | :data:`REASON_MAX_LENGTH`;|
|                  |                                  | never ``user_message``)   |
+------------------+----------------------------------+---------------------------+

``step_id`` on corrections identify the **trigger frame** (where
``correct()`` succeeded), not the frame that originally wrote the value.

No ``- digression`` without digression metadata on ``SkillInterrupted``:

- ``call:`` sub-flow — ``CALL`` frame; parent not paused (no ``SkillInterrupted``)
- Scope handler — ``activate`` → ``default_unsupported_request_handler``;
  repair is ``- out_of_scope`` / ``- out_of_domain`` (via
  ``UnsupportedRequestClassified``)
- Same-flow re-activate — dispatch no-op before lifecycle events

No ``- out_of_scope`` / ``- out_of_domain`` when:

- ``in_scope`` — scope handler ran; supported request, not repair
- ``classification_failed`` — judge failure writes memory only; no
  ``UnsupportedRequestClassified`` (or would be skipped if present)
"""

from __future__ import annotations

from typing import Iterable, List, Literal, Optional

from pydantic import BaseModel, ConfigDict

from rasa.shared.core.events import (
    Event,
    SkillCancelled,
    SkillInterrupted,
    UnsupportedRequestClassified,
    is_memory_write_event,
)

RepairType = Literal[
    "correction",
    "cancellation",
    "digression",
    "out_of_scope",
    "out_of_domain",
]

REPAIR_FIELD_ORDER: tuple[str, ...] = (
    "memory_key",
    "step_id",
    "skill_id",
    "from_step_id",
    "from_skill_id",
    "to_step_id",
    "to_skill_id",
    "reason",
)

REASON_MAX_LENGTH = 120
_SECTION_TITLE = "Conversation Repair"


class RepairOccurrence(BaseModel):
    """One repair line in a run report, with typed optional detail fields."""

    model_config = ConfigDict(frozen=True)

    repair_type: RepairType
    memory_key: Optional[str] = None
    step_id: Optional[str] = None
    skill_id: Optional[str] = None
    from_step_id: Optional[str] = None
    from_skill_id: Optional[str] = None
    to_step_id: Optional[str] = None
    to_skill_id: Optional[str] = None
    reason: Optional[str] = None


def _truncate_reason(reason: str, *, max_length: int = REASON_MAX_LENGTH) -> str:
    if len(reason) <= max_length:
        return reason
    return f"{reason[: max_length - 3]}..."


def _correction_occurrence(event: Event) -> RepairOccurrence | None:
    """Return a correction occurrence when ``event`` is a memory write with metadata."""
    if not is_memory_write_event(event):
        return None
    from rasa.mantle.state.repair_metadata import read_correction_metadata

    correction = read_correction_metadata(event)
    if correction is None:
        return None
    return RepairOccurrence(
        repair_type="correction",
        memory_key=event.key,
        step_id=correction.step_id,
        skill_id=correction.skill_id,
    )


def deduce_repair_occurrences(events: Iterable[Event]) -> List[RepairOccurrence]:
    """Map qualifying tracker audit events to repair occurrences in tracker order."""
    # Imported lazily so importing this module never pulls in the mantle snapshot
    # chain (this tool is reachable from the copilot MCP server entrypoint).
    from rasa.mantle.default_skills import (
        REQUEST_TYPE_IN_DOMAIN_OUT_OF_SCOPE,
        REQUEST_TYPE_OUT_OF_DOMAIN_OUT_OF_SCOPE,
    )
    from rasa.mantle.state.repair_metadata import read_digression_metadata

    # Match the labels the cannot_help dispatch stamps on
    # UnsupportedRequestClassified (single source of truth in default_skills), so
    # scope declines still surface in the report after the request_type values
    # were renamed.
    out_of_scope_label = REQUEST_TYPE_IN_DOMAIN_OUT_OF_SCOPE
    out_of_domain_label = REQUEST_TYPE_OUT_OF_DOMAIN_OUT_OF_SCOPE

    occurrences: List[RepairOccurrence] = []
    for event in events:
        if isinstance(event, SkillCancelled):
            occurrences.append(
                RepairOccurrence(
                    repair_type="cancellation",
                    step_id=event.step_id,
                    skill_id=event.skill_id,
                )
            )
        elif (correction_occurrence := _correction_occurrence(event)) is not None:
            occurrences.append(correction_occurrence)
        elif isinstance(event, SkillInterrupted):
            digression = read_digression_metadata(event)
            if digression is not None:
                occurrences.append(
                    RepairOccurrence(
                        repair_type="digression",
                        from_step_id=event.step_id,
                        from_skill_id=event.skill_id,
                        to_step_id=digression.to_step_id,
                        to_skill_id=digression.to_skill_id,
                    )
                )
        elif isinstance(event, UnsupportedRequestClassified):
            if event.label == out_of_scope_label:
                occurrences.append(
                    RepairOccurrence(
                        repair_type="out_of_scope",
                        reason=_truncate_reason(event.reason),
                    )
                )
            elif event.label == out_of_domain_label:
                occurrences.append(
                    RepairOccurrence(
                        repair_type="out_of_domain",
                        reason=_truncate_reason(event.reason),
                    )
                )
    return occurrences


def format_conversation_repair_section(
    occurrences: List[RepairOccurrence],
) -> List[str]:
    """Render the conversation-repair section lines for a run report."""
    lines = [f"--- {_SECTION_TITLE} ---"]
    if not occurrences:
        lines.append("observed: none")
        return lines

    for occurrence in occurrences:
        lines.append(f"- {occurrence.repair_type}")
        for field_name in REPAIR_FIELD_ORDER:
            value = getattr(occurrence, field_name)
            if value:
                lines.append(f"  {field_name}: {value}")
    return lines
